mapper.select:
	SELECT
	goods_spu.*,
	(SELECT sum(goods_sku.stock) FROM goods_sku goods_sku WHERE goods_sku.spu_id = goods_spu.id) AS stock,
	(SELECT sum(goods_sku.stock) FROM goods_sku goods_sku WHERE goods_sku.spu_id = goods_spu.id) AS stock_total
	FROM goods_spu goods_spu


		AND goods_spu.del_flag = '0'

			AND goods_spu.id = #{query.id}


			AND goods_spu.shop_id = #{query.shopId}


			AND goods_spu.shelf = #{query.shelf}


			AND goods_spu.verify_status = #{query.verifyStatus}


			AND goods_spu.category_first = #{query.categoryFirst}


			AND goods_spu.category_second = #{query.categorySecond}


			AND goods_spu.category_third = #{query.categoryThird}


			AND goods_spu.name LIKE CONCAT('%',#{query.name},'%')


			AND goods_spu.spu_code = #{query.spuCode}


			AND goods_spu.spec_type = #{query.specType}


			AND goods_spu.freight_type = #{query.freightType}


			AND goods_spu.brand_id = #{query.brandId}


			AND (SELECT sum(gs.stock) FROM goods_sku gs WHERE gs.spu_id = goods_spu.id) <= COALESCE(goods_spu.stock_warn_line, 20)


ORDER BY CASE WHEN goods_spu.verify_status = '0' THEN 0 ELSE 1 END

SELECT

FROM goods_spu goods_spu
WHERE goods_spu.id = #{id}

SELECT

FROM goods_spu goods_spu
WHERE goods_spu.id = #{id}

SELECT

FROM goods_spu goods_spu
WHERE goods_spu.id = #{id}
